// Append to global state
// window.leagueData.players = ... // Patched out to keep real players
tff1Teams.forEach(t => { if (!window.leagueData.teams.find(existing => existing.id === t.id)) window.leagueData.teams.push(t); });
tff1Players.forEach(p => { 
        const teamHasPlayers = window.leagueData.players.some(existing => existing.teamId === p.teamId);
        if (!teamHasPlayers) window.leagueData.players.push(p); 
    });

// RELEGATION CLEANUP: Remove teams that are now in 1.Lig from Super Lig (in case they load from data_superlig.js)
const relegatedIds = ['antalyaspor', 'kayserispor', 'sivasspor', 'karagumruk', 'bodrumspor', 'bodrumfk', 'istanbulspor', 'pendikspor'];
window.leagueData.teams = window.leagueData.teams.filter(t => !relegatedIds.includes(t.id) || t.leagueId === 'tff1');
// If a player belongs to these relegated teams, move their leagueId or just keep them but ensure team exists.
// Actually, data_tff1.js already generates new dummy players for them. 
// Let's remove the old Super Lig players for these teams to avoid duplicates.
window.leagueData.players = window.leagueData.players.filter(p => !relegatedIds.includes(p.teamId) || tff1Teams.find(t => t.id === p.teamId));
